package org.zhixiaoce.aperture;
import java.util.*;import android.view.KeyEvent;import org.json.JSONObject;
public class BackNavigationTest {
 static int count;static void ok(boolean b,String why){count++;if(!b)throw new AssertionError(why);}static long serial=100;
 static KeyEvent key(long t,int action,int repeat,boolean canceled){return new KeyEvent(t,action,4,repeat,canceled);}static void back(BackHarness h){long t=++serial;h.dispatchKeyEvent(key(t,0,0,false));h.dispatchKeyEvent(key(t,1,0,false));}
 static BackHarness fixture()throws Exception{BackHarness h=new BackHarness();h.playingView=false;h.view="series";h.sectionSite=new CinemaCatalog.Site("合成来源","https://example.invalid/api","stable-source",1,Collections.emptyMap());List<CinemaCatalog.Line> lines=new ArrayList<>();for(int n=0;n<2;n++){CinemaCatalog.Line l=new CinemaCatalog.Line("线路"+(n+1));for(int i=0;i<60;i++)l.episodes.add(new CinemaCatalog.Episode("第"+(i+1)+"集（合成完整长标题）","https://example.invalid/"+n+"/"+i));lines.add(l);}h.data=new CinemaCatalog.Item("film-42","合成影视剧","",lines);return h;}
 public static void main(String[] args)throws Exception{
 BackHarness h=fixture();h.openDetail(h.sectionSite,h.data,h::renderBrowse);ok(h.screen.equals("detail")&&h.networkReads==1,"initial details load once");h.detailScroll.scrollTo(0,527);h.shownActions.get(0).run.run();ok(h.screen.equals("player")&&h.shownCursor.scrollY==527,"play captures exact caller and detail scroll");h.online=false;h.vodPlan=new CinemaPlaybackPlan(h.vodPlan.lines,1,45,83000);back(h);
 ok(h.screen.equals("detail")&&h.detailRenders==2,"player Back restores detail instead of app home");ok(h.networkReads==1,"offline return does not refetch details");ok(h.shownSelection.line==1&&h.shownSelection.episode==45&&h.shownSelection.continuing,"line/episode/progress survive switching while playing");ok(h.shownCursor.scrollY==527&&!h.shownCursor.fullscreen,"detail context persists");
 back(h);ok(h.screen.equals("browse")&&h.browses==1&&h.exits==0,"second physical Back returns catalogue");ok(h.sectionPage==7&&h.loadedItems==80&&h.browseScrollY==963&&h.filterYear.equals("2026")&&h.filterArea.equals("中国")&&h.browseWord.equals("合成检索")&&h.sectionItemId.equals("film-42"),"source page/filter/search/anchor remain available");h.dispatchKeyEvent(key(serial,1,0,false));ok(h.exits==0,"duplicate key-up cannot skip catalogue to app home");h.dispatchKeyEvent(key(++serial,1,0,false));ok(h.exits==0,"orphan key-up cannot exit");back(h);ok(h.exits==1&&h.defaults==0,"only a fresh root Back exits; no native dispatch fallback");
 h=fixture();h.back=()->{throw new AssertionError("canceled Back executed");};long t=++serial;h.dispatchKeyEvent(key(t,0,0,false));h.dispatchKeyEvent(key(t,1,0,true));ok(h.defaults==0,"canceled Back consumed");t=++serial;h.dispatchKeyEvent(key(t,0,0,false));h.generation++;h.dispatchKeyEvent(key(t,1,0,false));ok(h.defaults==0,"old screen Back cannot execute new-screen return");t=++serial;h.dispatchKeyEvent(key(t,0,0,false));h.backPress.cancel();h.dispatchKeyEvent(key(t,1,0,false));ok(h.defaults==0,"focus cancellation discards old release");
 h=fixture();h.openDetail(h.sectionSite,h.data,h::renderBrowse);h.shownCursor.episodes=true;h.shownActions.get(0).run.run();h.playerControlsNavigation=true;back(h);ok(h.playingView&&!h.playerControlsNavigation&&h.detailRenders==1,"first Back leaves explicit controls");h.choicePanel=new BackHarness.Panel();back(h);ok(h.playingView&&h.choicePanel==null,"episode/line menu closes before playback");back(h);ok(h.screen.equals("detail"),"next Back restores detail");
 h=fixture();final BackHarness favorite=h;JSONObject ref=CinemaShelf.ref("vod",h.sectionSite.key,h.data.id,h.data.name,"");h.openOverview(ref,h.sectionSite,h.data,()->{favorite.screen="favorites";favorite.playingView=false;});h.online=false;back(h);ok(h.screen.equals("detail")&&h.sectionFullscreen,"saved-item playback returns standalone film information");back(h);ok(h.screen.equals("favorites")&&h.homes==0,"favorite origin is retained");
 h=fixture();h.playingView=true;h.liveQueue=true;h.livePanel=new BackHarness.Panel();h.livePanel.opened=true;back(h);ok(!h.livePanel.opened&&h.playingView,"live picker closes without exiting");h.programmePanel=new BackHarness.Panel();h.programmePanel.opened=true;back(h);ok(!h.programmePanel.opened&&h.playingView,"programme overlay closes without exiting");
 h=fixture();h.playingView=true;h.playerBack=null;h.back=null;back(h);ok(h.screen.equals("browse")&&h.exits==0,"missing player return recovers catalogue rather than finish");h.destroyed=true;h.onBackPressed();ok(h.exits==0,"destroyed callbacks ignored");
 System.out.println(count+" production Back/cached-details/offline/favorite/selection assertions passed with explicit JVM collaborators");
 }
}
